connect.lines:
with fetch: http GET https://api.camunda.org/supportTicket | result=ticket: response.body
with summarise: openai chat | authentication.token={{secrets.OPENAI_TOKEN}} | internal_prompt=summarise this support ticket: {{ticket.content}}
with post: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.text==summarise: {{summarise.resultVariable}} | data.channel=#support

connect.raw:
with fetch: http GET https://api.camunda.org/supportTicket | result=ticket: response.body
with summarise: openai chat | authentication.token={{secrets.OPENAI_TOKEN}} | internal_prompt=summarise this support ticket: {{ticket.content}}
with post: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.text==summarise: {{summarise.resultVariable}} | data.channel=#support

with append: google-sheets addValues | authentication.authType=refresh | authentication.oauthClientId={{google-sheets.clientId}} | authentication.oauthClientSecret={{google-sheets.clientSecret}} | authentication.oauthRefreshToken={{google-sheets.refreshToken}} | addValues.spreadsheetId={{google-sheets.id}} | addValues.worksheetName={{google-sheets.sheet}} | addValues.cellId=A1 | addValues.value={{lead.name}}
with notify: teams sendMessageToChannel | authentication.type=clientCredentials | authentication.credentials.clientId={{teams.clientId}} | authentication.credentials.tenantId={{teams.tenantId}} | authentication.credentials.clientSecret={{teams.clientSecret}} | data.sendMessageToChannel.groupId={{teams.group}} | data.sendMessageToChannel.channelId={{teams.channel}} | data.sendMessageToChannel.content==**Lead Submission**
    +Name: {{lead.name}}
    +Company: {{lead.company}}
    +Email: {{lead.email}}
    +Phone: {{lead.phone}}
    +Date: {{now()}}
